141	{
142	    frameZoomFactor_ = frameZoomFactor;
143	    
144	    NSRect winRect = [[self window] frame];
145	    NSRect viewRect = [self frame];
146	    
147	    // compute the margin width and margin height
148	    float diffX = winRect.size.width - viewRect.size.width;
149	    float diffY = winRect.size.height - viewRect.size.height;
150	    
151	    // new window width and height
152	    float newWindowWidth = (int)(viewRect.size.width * frameZoomFactor + diffX);
153	    float newWindowHeight = (int)(viewRect.size.height * frameZoomFactor + diffY);
154	    
155	    // display window in the center of the screen
